package scl_test

import (
	"encoding/json"
	"fmt"
	"os"
	"path/filepath"
	"sort"
	"testing"

	"github.com/otfabric/go-iec61850/scl"
)

// corpusManifest is the part of the OT Fabric SCL corpus's manifest.json
// this test reads (otfabric/iec61850-scl-corpus, generated by
// tools/manifest.py with sclparse).
type corpusManifest struct {
	Parser string `json:"parser"`
	Files  []struct {
		Path     string `json:"path"`
		Expected struct {
			Schema   *string        `json:"schema"`
			Parsed   bool           `json:"parsed"`
			Errors   *int           `json:"errors"`
			Warnings *int           `json:"warnings"`
			Codes    map[string]int `json:"codes"`
		} `json:"expected"`
	} `json:"files"`
}

// TestSCLCorpus parses every file of the OT Fabric SCL corpus with
// semantic validation, as `sclparse validate` does, and compares the
// detected schema, whether the file parses, and the diagnostics (counts and
// codes) with the corpus manifest. The corpus is private: the test runs
// when IEC61850_SCL_CORPUS names a checkout of it and skips otherwise;
// IEC61850_SCL_CORPUS_REQUIRE=1 turns the skip into a failure.
//
// A difference is a parser change to look at: a fix (regenerate the
// corpus manifest with the new sclparse and record it in its
// docs/FINDINGS.md) or a regression.
func TestSCLCorpus(t *testing.T) {
	root := os.Getenv("IEC61850_SCL_CORPUS")
	if root == "" {
		if os.Getenv("IEC61850_SCL_CORPUS_REQUIRE") == "1" {
			t.Fatal("IEC61850_SCL_CORPUS_REQUIRE=1 but IEC61850_SCL_CORPUS is not set")
		}
		t.Skip("IEC61850_SCL_CORPUS is not set (a checkout of otfabric/iec61850-scl-corpus)")
	}
	data, err := os.ReadFile(filepath.Join(root, "manifest.json"))
	if err != nil {
		t.Fatalf("corpus manifest: %v", err)
	}
	var m corpusManifest
	if err := json.Unmarshal(data, &m); err != nil {
		t.Fatalf("corpus manifest: %v", err)
	}
	if len(m.Files) == 0 {
		t.Fatal("corpus manifest lists no files")
	}
	t.Logf("%d files, expected outcomes from %s", len(m.Files), m.Parser)

	for _, f := range m.Files {
		t.Run(f.Path, func(t *testing.T) {
			path := filepath.Join(root, f.Path)
			raw, err := os.ReadFile(path)
			if err != nil {
				t.Fatal(err)
			}
			if f.Expected.Schema != nil {
				vi, err := scl.DetectVersion(raw)
				got := ""
				if err == nil {
					got = string(vi.Schema)
				}
				if got != *f.Expected.Schema {
					t.Errorf("schema = %q, want %q (%v)", got, *f.Expected.Schema, err)
				}
			}

			res, err := scl.ParseFileOpts(path, scl.ParseOptions{ValidateSemantic: true})
			if (err == nil) != f.Expected.Parsed {
				t.Fatalf("parsed = %v (%v), want %v", err == nil, err, f.Expected.Parsed)
			}
			if err != nil {
				return
			}
			errs, warns, codes := 0, 0, map[string]int{}
			for _, d := range res.Diagnostics {
				switch d.Severity {
				case scl.DiagError:
					errs++
				default:
					warns++
				}
				code := d.Code
				if code == "" {
					code = "uncoded"
				}
				codes[fmt.Sprintf("%s:%s", d.Severity, code)]++
			}
			if f.Expected.Errors != nil && errs != *f.Expected.Errors {
				t.Errorf("errors = %d, want %d", errs, *f.Expected.Errors)
			}
			if f.Expected.Warnings != nil && warns != *f.Expected.Warnings {
				t.Errorf("warnings = %d, want %d", warns, *f.Expected.Warnings)
			}
			if !sameCodes(codes, f.Expected.Codes) {
				t.Errorf("codes = %v, want %v", sortedCodes(codes), sortedCodes(f.Expected.Codes))
			}
		})
	}
}

func sameCodes(a, b map[string]int) bool {
	if len(a) != len(b) {
		return false
	}
	for k, v := range a {
		if b[k] != v {
			return false
		}
	}
	return true
}

func sortedCodes(m map[string]int) []string {
	out := make([]string, 0, len(m))
	for k, v := range m {
		out = append(out, fmt.Sprintf("%s=%d", k, v))
	}
	sort.Strings(out)
	return out
}
